  name: "Phone — filtered calendars",
  parameters: phoneParams,
  decorators: [phoneFrame],
  render: () => <CalendarAgenda width={PHONE_WIDTH} hiddenCalendarIds={["cal_oncall", "cal_hobby"]} />
